def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    pos = observation.get("self_position", {}) or {}
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    op = observation.get("opponent_position", {}) or {}
    ox = op.get("x", 0)
    oy = op.get("y", 0)

    resources = observation.get("resources", []) or []
    if isinstance(resources, list) and resources:
        best = None
        best_d2 = None
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            dx = rx - x
            dy = ry - y
            d2 = dx*dx + dy*dy
            if best_d2 is None or d2 < best_d2:
                best_d2 = d2
                best = (dx, dy)
        if best is not None:
            dx, dy = best
            if dx != 0:
                dx = 1 if dx > 0 else -1
            if dy != 0:
                dy = 1 if dy > 0 else -1
            return [dx, dy]

    obstacles = observation.get("obstacles", []) or []
    # Try to move toward center when no resources: prefer stepping toward center not blocked
    tx = max(0, min(grid_w - 1, grid_w // 2))
    ty = max(0, min(grid_h - 1, grid_h // 2))
    dx = 0
    dy = 0
    if x < tx:
        dx = 1
    elif x > tx:
        dx = -1
    if y < ty:
        dy = 1
    elif y > ty:
        dy = -1
    if dx != 0 or dy != 0:
        return [dx, dy]

    # If at goal position or no move decided, try to move away from opponent slightly
    dx = 0
    dy = 0
    if ox > x:
        dx = -1
    elif ox < x:
        dx = 1
    if oy > y:
        dy = -1
    elif oy < y:
        dy = 1
    if dx != 0 or dy != 0:
        return [dx if -1 <= dx <= 1 else 0, dy if -1 <= dy <= 1 else 0]

    # Fallback: stay
    return [0, 0]
